-- QUIPUS: EXISTING-PROJECT RECORDING AND CALENDAR UPGRADE (021 + 022)
-- Generated by scripts/package-supabase-setup.py --recording-calendar-upgrade.
-- Requires migrations 001-020 already installed. No credentials included.
-- Run this ENTIRE file once in Supabase > SQL Editor > New query.
-- This migration does not delete any existing recording or storage object.
-- Future silence cleanup requires validated evidence and a processing lease.
-- Calendar hiding preserves audio, transcripts, history and Google events.
-- Stop on error: original migration transaction boundaries are preserved.
-- SQL Editor does not populate the Supabase CLI migration ledger.

do $quipus_recording_upgrade$
begin
  if to_regclass('public.lantern_sessions') is null
     or to_regclass('public.recordings') is null
     or to_regclass('public.recording_audio_sources') is null
     or to_regclass('public.recording_audio_deletions') is null then
    raise exception 'Install missing migrations 001-020 before this upgrade';
  end if;
  if to_regclass('public.recording_discard_decisions') is not null then
    raise exception 'Migration 021 already exists: apply only missing migrations, such as 022';
  end if;
end
$quipus_recording_upgrade$;

-- BEGIN MIGRATION 021_short_silence_discard.sql
-- Source SHA-256: ebcda31d97b9a2614e603c4b9e1cb30bb3ab93d63d430449c86c4d7109ec3e66
begin;

-- Authoritative evidence is service-only. Public recording metadata cannot
-- authorize deletion, and this migration performs NO historical cleanup.
create table public.recording_discard_decisions (
  session_id uuid primary key references public.lantern_sessions(id) on delete cascade,
  recording_id uuid not null unique references public.recordings(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  device_id uuid not null references public.devices(id) on delete cascade,
  audio_event_id uuid not null,
  reason text not null check(reason='short_digital_silence'),
  policy_version text not null check(policy_version='digital-constant-v1'),
  source_evidence jsonb not null,
  no_speech_responses integer not null check(no_speech_responses>0),
  created_at timestamptz not null default now()
);
alter table public.recording_discard_decisions enable row level security;
revoke all on public.recording_discard_decisions from public,anon,authenticated;
grant all on public.recording_discard_decisions to service_role;

create function public.discard_quipus_short_silence(
  p_session_id uuid,p_user_id uuid,p_device_id uuid,p_lease_token uuid,
  p_evidence jsonb,p_no_speech_responses integer)
returns boolean language plpgsql security definer set search_path=public as $$
declare s public.lantern_sessions; r public.recordings; a public.lantern_audio_uploads;
  j public.lantern_processing_jobs; e jsonb; source_count integer; paths text[]; extra text[];
  expected text[]; samples bigint; bytes bigint;
begin
  select * into s from public.lantern_sessions where id=p_session_id
    and user_id=p_user_id and device_id=p_device_id for update;
  if not found or not exists(select 1 from public.devices d where d.id=p_device_id and d.user_id=p_user_id and d.revoked_at is null) then raise exception 'Session not found'; end if;
  if exists(select 1 from public.recording_discard_decisions d where d.session_id=s.id
    and d.user_id=p_user_id and d.device_id=p_device_id and d.recording_id=s.recording_id
    and d.audio_event_id=s.audio_event_id) then return true; end if;
  select * into j from public.lantern_processing_jobs where session_id=s.id
    and user_id=p_user_id and state='running' and lease_token=p_lease_token and lease_until>now() for update;
  if not found then raise exception 'Processing lease lost'; end if;
  if s.ended_at is null or s.capture_ended_at is null or s.recording_id is null
    or s.final_transcription is not null or s.meeting_id is not null
    or (s.transcript_segments is not null and s.transcript_segments<>'[]'::jsonb)
    or exists(select 1 from public.meetings m where m.user_id=p_user_id
      and (m.recording_id=s.recording_id or m.client_reference='hardware:'||s.id::text))
    or exists(select 1 from public.transcripts t where t.recording_id=s.recording_id)
    then raise exception 'Recording has speech or meeting evidence'; end if;
  select * into r from public.recordings where id=s.recording_id and user_id=p_user_id
    and device_id=p_device_id and audio_deleted_at is null for update;
  if not found then raise exception 'Recording not found'; end if;
  select * into a from public.lantern_audio_uploads where session_id=s.id
    and event_id=s.audio_event_id and storage_path=r.storage_path and verified_at is not null for update;
  if not found then raise exception 'Verified archive required'; end if;
  expected:=s.expected_audio_sources;
  if expected is null or cardinality(expected)<1 or cardinality(expected)>2
    or not 'onboard'=any(expected) or not expected<@array['onboard','phone']::text[]
    or cardinality(expected)<>(select count(distinct kind) from unnest(expected) kind)
    or jsonb_typeof(p_evidence) is distinct from 'array'
    or jsonb_array_length(p_evidence)<>cardinality(expected)
    or p_no_speech_responses is null or p_no_speech_responses<1
    then raise exception 'Invalid silence evidence'; end if;
  -- Every expected source must independently qualify. A quiet onboard track
  -- cannot erase speech captured by a phone, nor can a combined-track mix.
  for e in select value from jsonb_array_elements(p_evidence) loop
    if jsonb_typeof(e) is distinct from 'object' or not coalesce(e->>'sourceKind','')=any(s.expected_audio_sources)
      or (select count(*) from jsonb_array_elements(p_evidence) x where x->>'sourceKind'=e->>'sourceKind')<>1
      or coalesce(e->>'sha256','') !~ '^[a-f0-9]{64}$'
      or coalesce(e->>'sampleCount','') !~ '^[0-9]+$'
      or coalesce(e->>'totalBytes','') !~ '^[0-9]+$'
      or coalesce(e->>'constantSample','') !~ '^-?[0-9]+$'
      then raise exception 'Invalid silence source'; end if;
    samples:=(e->>'sampleCount')::bigint; bytes:=(e->>'totalBytes')::bigint;
    if samples<1 or samples>=80000 or bytes<>samples*2+44 or abs((e->>'constantSample')::integer)>128
      then raise exception 'Recording is not short digital silence'; end if;
    if e->>'sourceKind'='onboard' then
      if bytes<>a.total_bytes or e->>'sha256'<>a.sha256 then raise exception 'Archive evidence changed'; end if;
    else
      select count(*) into source_count from public.recording_audio_sources x where x.session_id=s.id
        and x.user_id=p_user_id and x.recording_id=r.id and x.source_kind='phone'
        and x.committed_at is not null and x.verified_at is not null
        and x.byte_length=bytes and x.sha256=e->>'sha256';
      if source_count<>1 then raise exception 'Phone evidence changed'; end if;
    end if;
  end loop;
  if (select count(*) from public.recording_audio_sources x where x.session_id=s.id)
    <>cardinality(s.expected_audio_sources)-1 then raise exception 'Unexpected recording source'; end if;
  paths:=array[r.storage_path];
  if r.consolidated_storage_path is not null then paths:=paths||array[r.consolidated_storage_path]; end if;
  select array_agg(storage_path) into extra from public.recording_audio_sources where recording_id=r.id and user_id=p_user_id;
  paths:=paths||coalesce(extra,array[]::text[]);
  select array_agg(storage_path) into extra from public.recording_audio_derivatives where recording_id=r.id and user_id=p_user_id;
  paths:=paths||coalesce(extra,array[]::text[]);
  if exists(select 1 from unnest(paths) p where split_part(p,'/',1)<>p_user_id::text
    or position(chr(92) in p)>0 or p like '%..%' or position('%' in p)>0) then raise exception 'Invalid recording owner path'; end if;
  insert into public.recording_discard_decisions(session_id,recording_id,user_id,device_id,audio_event_id,
    reason,policy_version,source_evidence,no_speech_responses)
    values(s.id,r.id,p_user_id,p_device_id,s.audio_event_id,'short_digital_silence','digital-constant-v1',p_evidence,p_no_speech_responses);
  insert into public.recording_audio_deletions(recording_id,user_id,object_paths)
    values(r.id,p_user_id,paths);
  update public.lantern_sessions set processing_stage='discarded_silence',processing_error=null where id=s.id;
  update public.lantern_processing_jobs set state='ready',lease_until=null,last_error=null,updated_at=now()
    where session_id=s.id and lease_token=p_lease_token;
  return true;
end $$;

-- This claims only the one positively identified fluke, never unrelated or
-- historical audio. Existing storage-first completion validates path changes.
create function public.claim_quipus_silence_cleanup(p_recording_id uuid,p_user_id uuid)
returns setof public.recording_audio_deletions language plpgsql security definer set search_path=public as $$
begin
  return query update public.recording_audio_deletions d set state='working',attempts=d.attempts+1,
    lease_token=gen_random_uuid(),lease_until=now()+interval '5 minutes'
    where d.recording_id=p_recording_id and d.user_id=p_user_id and d.available_at<=now()
      and (d.state='pending' or (d.state='working' and d.lease_until<now()))
      and exists(select 1 from public.recording_discard_decisions x where x.recording_id=d.recording_id and x.user_id=d.user_id)
    returning d.*;
end $$;
revoke all on function public.discard_quipus_short_silence(uuid,uuid,uuid,uuid,jsonb,integer) from public,anon,authenticated;
revoke all on function public.claim_quipus_silence_cleanup(uuid,uuid) from public,anon,authenticated;
grant execute on function public.discard_quipus_short_silence(uuid,uuid,uuid,uuid,jsonb,integer) to service_role;
grant execute on function public.claim_quipus_silence_cleanup(uuid,uuid) to service_role;
notify pgrst,'reload schema';
commit;

-- END MIGRATION 021_short_silence_discard.sql

-- BEGIN MIGRATION 022_recording_calendar_visibility.sql
-- Source SHA-256: aa74619e9be90e0d6d6e39d1a59a6b682cf43d6f99e735271874b9b36a8899ba
begin;
-- Display preference only: audio, transcript, Google events and invitations are
-- retained. Stable references also cover hardware sessions still processing.
create table if not exists public.calendar_recording_preferences (
  user_id uuid not null references public.profiles(id) on delete cascade,
  conversation_reference text not null check (length(conversation_reference) between 1 and 160),
  hidden boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (user_id, conversation_reference)
);
alter table public.calendar_recording_preferences enable row level security;
-- Browser access goes through authenticated, explicitly owner-scoped routes.
revoke all on public.calendar_recording_preferences from public, anon, authenticated;
grant all on public.calendar_recording_preferences to service_role;
notify pgrst, 'reload schema';
commit;

-- END MIGRATION 022_recording_calendar_visibility.sql

select 'Quipus recording and calendar upgrade complete' as status,
  to_regclass('public.recording_discard_decisions') is not null as silence_policy_installed,
  to_regclass('public.calendar_recording_preferences') is not null as calendar_visibility_installed;
